import { Amplify } from "aws-amplify";
// Bundled at build time (not fetched), so a cached service worker can never pair old code
// with a different backend. Generated by `ampx sandbox` / `ampx pipeline-deploy`.
import outputs from "../../amplify_outputs.json";

// Default token storage on the web is localStorage: the session survives offline reloads.
Amplify.configure(outputs);
